int nextValue(const unsigned char *data, size_t totalBits, size_t *pos, unsigned int width, int *out) {
    size_t start = *pos;
    if (width < 1 || width > 31 || start > totalBits) return -1;
    if (start == totalBits) return 0;
    if (width > totalBits - start) return -1;
    unsigned int raw = getBits(data, start, width);
    *out = decodeSigned(raw, width);
    *pos = start + width;
    return 1;
}

